const HCOLORS=["var(--h1)","var(--h2)","var(--h3)","var(--h4)"];
const TABS=[["today","Today"],["todo","To-do"],["people","People"],["habits","Habits"],["goals","Goals"],["money","Money"]];
const gear=()=>`<button class="iconbtn gearb" data-a="tab" data-t="more" aria-label="Settings${UPD.state==="avail"?", update available":""}">${ico("gear")}${UPD.state==="avail"&&S.updSkip!==UPD.tag?`<i class="dot"></i>`:""}</button>`,backBtn=(a,t)=>`<button class="iconbtn" data-a="${a}" ${t?`data-t="${t}"`:""} aria-label="Back">${ico("back")}</button>`;
const empty=(t,s)=>`<div class="empty"><b>${t}</b>${s||""}</div>`;
const sel=(bind,arr,v)=>`<select data-bind="${bind}">${arr.map(x=>{const[val,lab]=Array.isArray(x)?x:[x,x];return`<option value="${esc(val)}" ${String(val)===String(v)?"selected":""}>${esc(lab)}</option>`}).join("")}</select>`;

/* ================= health ================= */
function daily(){const m={};S.w.forEach(e=>(m[e.d]=m[e.d]||[]).push(e.kg));return Object.keys(m).sort().map(k=>({k,label:fmt(P(k)),kg:mean(m[k]),n:m[k].length}))}
function group(mode){if(mode==="day")return daily();const m={};daily().forEach(p=>{const d=P(p.k),key=mode==="week"?iso(monday(d)):p.k.slice(0,7);(m[key]=m[key]||[]).push(p)});return Object.keys(m).sort().map(k=>{const a=m[k];return{k,label:mode==="week"?"Wk of "+fmt(P(k)):MON[+k.slice(5)-1]+" "+k.slice(2,4),kg:mean(a.map(x=>x.kg)),n:sum(a.map(x=>x.n))}})}
function runStreak(has,sched,end){sched=sched||(()=>true);end=end||T;let c=0,d=has(iso(end))?end:add(end,-1),guard=0;while(guard++<1000){if(!sched(d)){d=add(d,-1);continue}if(has(iso(d))){c++;d=add(d,-1)}else break}return c}
function bestStreak(keys,sched){sched=sched||(()=>true);const s=new Set(keys);if(!s.size)return 0;const ks=[...s].sort();let best=0,run=0,d=P(ks[0]);while(d<=T){if(sched(d)){if(s.has(iso(d))){run++;best=Math.max(best,run)}else if(d<T)run=0}d=add(d,1)}return best}
function wStreak(){const ks=daily().map(p=>p.k),s=new Set(ks);return{c:runStreak(k=>s.has(k)),best:bestStreak(ks),today:s.has(iso(T))}}
const bmiOf=kg=>S.height?kg/((S.height/100)**2):null,cat=b=>b<18.5?["Underweight","var(--acc)"]:b<25?["Healthy","var(--ok)"]:b<30?["Overweight","var(--warn)"]:["Obese","var(--bad)"];
function project(){if(!S.goal)return"Set a goal weight to see when you’ll reach it.";const d=daily().slice(-28);if(d.length<5)return"Log on a few more days to see when you’ll reach "+S.goal+" kg.";const x=d.map(p=>diff(p.k)),y=d.map(p=>p.kg),mx=mean(x),my=mean(y),sl=sum(x.map((v,i)=>(v-mx)*(y[i]-my)))/sum(x.map(v=>(v-mx)**2)),cur=y[y.length-1],wk=(sl*7).toFixed(2);
 if(Math.abs(sl)<.002)return"Your weight is steady. Goal: "+S.goal+" kg.";const n=(S.goal-cur)/sl;if(n<=0)return"You’re trending away from "+S.goal+" kg ("+(sl>0?"+":"")+wk+" kg/week).";if(n>730)return"At "+wk+" kg/week, the goal is over 2 years away.";return"At "+wk+" kg/week you’ll reach "+S.goal+" kg around <b>"+fmt(add(T,Math.round(n)))+"</b>."}
function heatGrid(level,color){const mon=add(monday(T),-19*7),c=[];for(let i=0;i<140;i++){const d=add(mon,i);if(d>T){c.push('<i class="x"></i>');continue}c.push(`<i style="--l:${level(d)}" title="${iso(d)}"></i>`)}return`<div class="heat" style="--hc:${color||"var(--acc)"}" role="img" aria-label="Heat map of the last 20 weeks">${c.join("")}</div>`}
function chart(){const s=group(S.mode),W=360,H=170,Pd=26,vs=s.map(p=>p.kg).concat(S.goal?[S.goal]:[]),lo=Math.min(...vs)-.5,hi=Math.max(...vs)+.5,X=i=>Pd+(s.length>1?i*(W-Pd-10)/(s.length-1):0),Y=v=>H-24-(v-lo)/(hi-lo)*(H-40),ix={};s.forEach((p,i)=>ix[p.k]=i);
 const ln=s.map((p,i)=>(i?"L":"M")+X(i).toFixed(1)+" "+Y(p.kg).toFixed(1)).join(""),raw=S.mode==="day"?S.w.filter(e=>ix[e.d]!=null).map(e=>`<circle cx="${X(ix[e.d])}" cy="${Y(e.kg)}" r="2.4" fill="none" stroke="var(--mut)" stroke-width="1"/>`).join(""):"",la=s[s.length-1];
 return`<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Weight chart" style="font-family:inherit">${S.goal?`<line x1="${Pd}" x2="${W-6}" y1="${Y(S.goal)}" y2="${Y(S.goal)}" stroke="var(--ok)" stroke-dasharray="4 4"/><text x="${Pd}" y="${Y(S.goal)-5}" fill="var(--ok)" font-size="11">Goal ${S.goal}</text>`:""}<path d="${ln}" fill="none" stroke="var(--acc)" stroke-width="2.4" stroke-linejoin="round"/>${raw}<circle cx="${X(s.length-1)}" cy="${Y(la.kg)}" r="4.5" fill="var(--acc)"/><text x="${Pd}" y="${H-6}" fill="var(--mut)" font-size="11">${s[0].label}</text><text x="${W-6}" y="${H-6}" text-anchor="end" fill="var(--mut)" font-size="11">${la.label}</text></svg>`}
/* water & sleep */
const wToday=()=>S.water.log[iso(T)]||0;
const sleepMin=e=>{const[a,b]=e.b.split(":").map(Number),[c,d]=e.w.split(":").map(Number);return((c*60+d)-(a*60+b)+1440)%1440||1440};
const fmtDur=m=>Math.floor(m/60)+"h"+(m%60?" "+String(m%60).padStart(2,"0")+"m":"");
/* habits */
const hSched=h=>d=>!h.days||h.days.length===7||h.days.includes(d.getDay());
const stMin=(k,app)=>{const u=S.usage&&S.usage[k];if(!u)return null;if(!app)return u.total||0;const a=(u.apps||[]).find(x=>x.pkg===app);return a?a.min:0};
const hVal=(h,d)=>h.kind==="screen"?(stMin(d||iso(T),h.app)||0):(h.log&&h.log[d||iso(T)])||0,hDone=(h,d)=>{if(h.kind==="screen"){const v=stMin(d||iso(T),h.app);return v!=null&&v<=(h.target||0)}const v=hVal(h,d);return h.kind==="count"?v>=(h.target||1):!!v};
const isScr=h=>h.kind==="screen";
const hStreak=h=>runStreak(k=>hDone(h,k)||frozen(k),hSched(h)),hBest=h=>bestStreak(Object.keys(h.log||{}).filter(k=>hDone(h,k)).concat(Object.keys(S.frozen||{})),hSched(h));
const hToday=()=>S.habits.filter(h=>hSched(h)(T));

/* ================= to-do ================= */
const tdOld=(a,b)=>a.done-b.done||(b.star?1:0)-(a.star?1:0)||(a.rem||"99").localeCompare(b.rem||"99")||a.id-b.id;
const tdSort=(a,b)=>a.done-b.done||(a.ord==null?1e12:a.ord)-(b.ord==null?1e12:b.ord)||a.id-b.id;
const maxOrd=()=>Math.max(0,...S.todos.map(x=>x.ord||0)),minOrd=()=>Math.min(0,...S.todos.map(x=>x.ord==null?0:x.ord));
if(S.todos.some(x=>x.ord==null))S.todos.slice().sort(tdOld).forEach((x,i)=>{if(x.ord==null)x.ord=i+1});
const tdToday=()=>S.todos.filter(x=>x.d===iso(T)||(x.d<iso(T)&&!x.done)).sort(tdSort);
const tdNext=()=>S.todos.filter(x=>x.d>iso(T)).sort((a,b)=>(a.d+(a.rem||"99")).localeCompare(b.d+(b.rem||"99")));
const tdFired=()=>tdToday().filter(x=>!x.done&&x.rem&&x.d===iso(T)&&x.rem<=nowHM());
const tdStats=()=>{const a=tdToday();return{a,dn:a.filter(x=>x.done),left:a.filter(x=>!x.done)}};
const REP={none:"Does not repeat",daily:"Every day",weekdays:"Weekdays",weekly:"Every week",monthly:"Every month"},REPS={daily:"Daily",weekdays:"Weekdays",weekly:"Weekly",monthly:"Monthly"};
function nextDate(s,rep){const d=P(s);if(rep==="daily")d.setDate(d.getDate()+1);else if(rep==="weekly")d.setDate(d.getDate()+7);else if(rep==="monthly"){const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()))}else if(rep==="weekdays"){do d.setDate(d.getDate()+1);while(d.getDay()===0||d.getDay()===6)}return iso(d)}
function setDone(x,done,at){if(done&&!x.done&&!at)buzz("done");x.done=done;x.at=done?(at||nowHM()):"";x.dd=done?iso(T):"";
 if(done&&x.rep&&x.rep!=="none"&&!x.nx){let n=x.d;do n=nextDate(n,x.rep);while(n<=iso(T));const lg=x.gid&&S.goals.find(g=>g.id===x.gid);if(lg&&n>lg.due)return null;const c={...x,id:nid(),d:n,done:false,at:"",dd:"",nx:null,subs:(x.subs||[]).map(s=>({...s,done:false}))};S.todos.push(c);x.nx=c.id;return c}
 if(!done&&x.nx){const c=S.todos.find(y=>y.id===x.nx);if(c&&!c.done)S.todos=S.todos.filter(y=>y.id!==c.id);x.nx=null}return null}
function review(){const{a,dn,left}=tdStats();return{a:a.length?"You finished "+dn.length+" of "+a.length+" today":"Nothing on your list today",b:left.length?"Still open: "+left.map(x=>x.t).join(", "):a.length?"Everything is crossed off. Nice work.":"Add tomorrow’s tasks before bed?"}}
function tdRow(x,swipe,compact){const old=x.d<iso(T)&&!x.done,op=S.openT===x.id,subs=x.subs||[],sd=subs.filter(s=>s.done).length;
 const meta=x.done?["Done "+(x.at||"")]:[old?`<span class="late">From ${dl(x.d)}</span>`:"",x.rem?"Reminder "+x.rem:"",x.rep&&x.rep!=="none"?"↻ "+REPS[x.rep]:"",subs.length?sd+"/"+subs.length+" steps":""].filter(Boolean);
 const row=`<div class="tdo ${x.done?"dn":""}" ${swipe&&!op?`data-sw="${x.id}"`:""}><input type="checkbox" data-a="tdone" data-id="${x.id}" ${x.done?"checked":""} aria-label="Mark ${esc(x.t)} done"><div class="g" data-a="topen" data-id="${x.id}"><p class="tt">${esc(x.t)}</p>${meta.length?`<p class="sm mut">${meta.join(" · ")}</p>`:""}${!compact&&!op&&subs.length&&!x.done?`<div class="isubs">${subs.map((s,i)=>`<label class="isub ${s.done?"dn":""}"><input type="checkbox" data-a="sdone" data-id="${x.id}" data-i="${i}" ${s.done?"checked":""} aria-label="Step done"><span class="tt">${esc(s.t)}</span></label>`).join("")}<button class="addstep" data-a="topen" data-id="${x.id}">+ Add step</button></div>`:""}</div><button class="stb ${x.star?"on":""}" data-a="tstar" data-id="${x.id}" aria-label="${x.star?"Remove priority":"Mark as priority"}">${svg("star")}</button></div>`;
 const det=op?`<div class="tx"><p class="sm mut" style="margin:0 0 4px">Steps</p><div class="r" style="border:0;padding:0 0 4px"><input id="subin" data-sub="${x.id}" aria-label="New step" autocomplete="off" enterkeyhint="done"><button class="btn s" data-a="sadd" data-id="${x.id}">Add step</button></div><div class="subs">${subs.map((s,i)=>`<div class="sub ${s.done?"dn":""}"><input type="checkbox" data-a="sdone" data-id="${x.id}" data-i="${i}" ${s.done?"checked":""} aria-label="Step done"><span class="g tt">${esc(s.t)}</span><button class="xb" data-a="sdel" data-id="${x.id}" data-i="${i}" aria-label="Remove step">×</button></div>`).join("")}</div>
 <div class="g2"><div><label class="f">Day</label>${pf("task:"+x.id+":d","date",x.d)}</div><div><label class="f">Reminder</label>${pf("task:"+x.id+":rem","time",x.rem||"",{clear:1,none:"No reminder"})}</div></div>
 <label class="f">Repeat</label><div class="chips wrap">${Object.keys(REP).map(k=>`<button class="chip ${(x.rep||"none")===k?"on":""}" data-a="trep" data-id="${x.id}" data-v="${k}">${k==="none"?"Never":REPS[k]}</button>`).join("")}</div>
 <div style="display:flex;gap:8px;margin-top:12px"><button class="btn s" style="color:var(--bad)" data-a="tdel" data-id="${x.id}">Delete task</button><button class="btn s" style="margin-left:auto" data-a="topen" data-id="${x.id}">Close</button></div></div>`:"";
 return swipe&&!op?`<div class="swr"><div class="swl">Tomorrow →</div><div class="swrr">✓ Done</div>${row}</div>`:`<div class="swr">${row}${det}</div>`}
const remBanners=()=>tdFired().map(x=>`<div class="alert"><b>Reminder: ${esc(x.t)}</b><p class="sm mut">Set for ${x.rem}</p><div class="acts"><button class="btn s p" data-a="tdone1" data-id="${x.id}">Mark done</button><button class="btn s" data-a="tsnooze" data-id="${x.id}">In 1 hour</button></div></div>`).join("");

/* ================= people ================= */
const pById=id=>S.people.find(p=>p.id===id);
const upcoming=()=>S.people.filter(p=>p.bd).map(p=>({k:"b",ref:p,id:p.id,n:p.n,m:p.bd.m,d:p.bd.d,n2:until(p.bd.m,p.bd.d)})).concat(S.dates.map(x=>({k:"o",ref:x,id:x.id,n:x.n,m:x.m,d:x.d,n2:until(x.m,x.d)}))).sort((a,b)=>a.n2-b.n2);
const workers=()=>S.people.filter(p=>p.cad>0).map(p=>({...p,dd:diff(p.next)})).sort((a,b)=>a.dd-b.dd);
const callsFor=d=>S.calls.filter(c=>c.d===d&&!c.done).sort((a,b)=>a.t.localeCompare(b.t));
const callWho=c=>{const p=pById(c.pid);return p?p.n:(c.who||"Someone")};
function dateRow(e){const b=e.k==="b",r=e.ref,op=S.openP===e.k+e.id,oc=add(T,e.n2);
 return`<div class="dr"><button class="drow" data-a="popen" data-k="${e.k}" data-id="${e.id}" aria-expanded="${op}"><span class="dd"><b>${e.d}</b><small>${WD[oc.getDay()]}</small></span><span class="g"><span class="nm">${esc(e.n)}</span><span class="sm mut">${b?"Birthday · "+zodiac(e.m,e.d)+(r.cad>0?" · Work":""):"Date"}</span></span><span class="sm ${e.n2<=1?"soon":"mut"}">${e.n2===0?"Today":e.n2===1?"Tomorrow":e.n2+" days"}</span></button>
 ${b&&r.gift?`<button class="gchip ${r.bought?"ok":""}" data-a="bought" data-id="${r.id}">${r.bought?"✓ Gift bought":"Gift to buy"}${r.idea?" · "+esc(r.idea):""}</button>`:""}
 ${op?`<div class="dx">${b&&r.note?`<p class="sm" style="margin-bottom:10px">${esc(r.note)}</p>`:""}<p class="sm mut" style="margin-bottom:8px">Remind me</p><div class="chips wrap">${[[0,"Same day"],[1,"1 day before"],[7,"1 week before"]].map(([v,t])=>`<button class="chip ${r.rem.includes(v)?"on":""}" data-a="prem" data-k="${e.k}" data-id="${e.id}" data-v="${v}">${t}</button>`).join("")}</div>
 <div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap"><button class="btn s" data-a="${b?"pedit":"dedit"}" data-id="${e.id}">Edit</button>${b?`<button class="btn s" data-a="callfor" data-id="${e.id}">Schedule a call</button>`:""}<button class="btn s" style="color:var(--bad)" data-a="${b?"pdel":"ddel"}" data-id="${e.id}">Delete</button></div></div>`:""}</div>`}
function workRow(p){const op=S.openP==="w"+p.id;return`<div class="r" style="flex-wrap:wrap"><div class="g" data-a="popen" data-k="w" data-id="${p.id}" style="cursor:pointer"><h3>${esc(p.n)}</h3><p class="mut sm">${[p.co,p.stage].filter(Boolean).map(esc).join(" · ")}</p><p class="sm">${due(p.next)} · last contact ${-diff(p.last)===0?"today":-diff(p.last)+"d ago"}</p></div>${p.tag?`<span class="tag">${esc(p.tag)}</span>`:""}
 <div class="g2" style="width:100%"><button class="btn s" data-a="snooze" data-id="${p.id}">Snooze 2 days</button><button class="btn s p" data-a="fdone" data-id="${p.id}">Done</button></div>
 ${op?`<div style="width:100%">${p.note?`<p class="sm" style="margin:4px 0 8px">${esc(p.note)}</p>`:""}<p class="sm mut">Follow up every ${p.cad} days${p.bd?" · Birthday "+p.bd.d+" "+MON[p.bd.m]:""}</p><div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap"><button class="btn s" data-a="pedit" data-id="${p.id}">Edit</button><button class="btn s" data-a="callfor" data-id="${p.id}">Schedule a call</button><button class="btn s" style="color:var(--bad)" data-a="pdel" data-id="${p.id}">Delete</button></div></div>`:""}</div>`}
function callRow(c){return`<div class="r"><label class="chk g" style="min-height:0"><input type="checkbox" data-a="cdone" data-id="${c.id}" ${c.done?"checked":""}><span><b style="${c.done?"text-decoration:line-through;color:var(--mut)":""}">${esc(c.topic)}</b><br><span class="mut sm">${esc(callWho(c))} · ${dl(c.d)} ${c.t}${c.rep&&c.rep!=="none"?" · "+REPS[c.rep]:""}</span></span></label><button class="xb" data-a="cdel" data-id="${c.id}" aria-label="Delete call">×</button></div>`}

/* ================= goals (SMART) ================= */
const GP={week:"This week",month:"This month",year:"This year"};
function pRange(p,ref){ref=ref||T;if(p==="week"){const s=monday(ref);return[s,add(s,6)]}if(p==="month")return[new Date(ref.getFullYear(),ref.getMonth(),1),new Date(ref.getFullYear(),ref.getMonth()+1,0)];return[new Date(ref.getFullYear(),0,1),new Date(ref.getFullYear(),11,31)]}
const pLabel=(p,s)=>p==="week"?"Week of "+fmt(s):p==="month"?MONL[s.getMonth()]+" "+s.getFullYear():String(s.getFullYear());
function pace(g){const s=P(g.start),e=P(g.due),total=Math.max(1,Math.round((e-s)/864e5)+1),el=Math.min(total,Math.max(0,Math.round((T-s)/864e5)+1)),exp=g.target*el/total,left=Math.max(0,Math.round((e-T)/864e5));
 if(g.cur>=g.target)return["Achieved","var(--ok)"];if(T>e)return["Ended at "+g.cur+" of "+g.target,"var(--mut)"];if(g.cur>=exp*.9)return["On track · "+plural(left,"day")+" left","var(--ok)"];const need=Math.ceil(g.target-g.cur);return["Behind · "+need+" to go, "+(left===0?"last day":plural(left+1,"day")+" left"),"var(--warn)"]}
const smartOf=f=>({S:!!(f.s&&f.s.trim()),M:+f.target>0&&!!(f.unit&&f.unit.trim()),A:!!(f.a&&f.a.trim()),R:!!(f.r&&f.r.trim()),T:!!f.due});
const smartBadges=f=>{const o=smartOf(f);return`<div class="smart" aria-label="SMART checklist">${"SMART".split("").map(k=>`<span class="${o[k]?"on":""}">${k}</span>`).join("")}</div>`};
function goalSrc(g){if(g.track==="pot"){const p=(S.pots||[]).find(x=>x.id===g.pid);return"Follows your pot “"+(p?p.n:"deleted")+"”"}if(g.track==="task"){const t=S.todos.filter(x=>x.gid===g.id).sort((a,b)=>b.id-a.id)[0];return"Counted from your task “"+(t?t.t:"deleted")+"”"+(g.per>1?" · "+g.per+" each time":"")}if(g.track==="habit"){const h=S.habits.find(x=>x.id===g.hid);return"Counted from your habit “"+(h?h.n:"deleted")+"”"+(g.per>1?" · "+g.per+" each tick":"")}return""}
function goalCard(g){const op=S.openG===g.id,pc=Math.min(100,Math.round(g.cur/g.target*100)),[st,col]=pace(g),auto=g.track==="task"||g.track==="habit"||g.track==="pot";
 return`<div class="box gc"><div class="r sb" style="border:0;padding:0;gap:12px"><div class="g" data-a="gopen" data-id="${g.id}" style="cursor:pointer"><h3>${esc(g.s)}</h3><p class="sm" style="margin-top:2px"><b>${+g.cur.toFixed(2)}</b> of ${g.target} ${esc(g.unit)} · <span style="color:${col}">${st}</span></p></div>${auto?`<span class="ring" style="--p:${pc}">${pc}%</span>`:`<button class="plus1" data-a="gstep" data-id="${g.id}" data-v="1" aria-label="Add one">+1</button>`}</div>
 <div class="bar"><i style="width:${pc}%;background:${g.cur>=g.target?"var(--ok)":"var(--acc)"}"></i></div>${auto?`<p class="sm mut" style="margin-top:8px">↻ ${esc(goalSrc(g))}</p>`:""}
 ${op?`<div class="smartd"><p><b>S</b> ${esc(g.s)}</p><p><b>M</b> ${g.target} ${esc(g.unit)}</p>${g.a?`<p><b>A</b> ${esc(g.a)}</p>`:""}${g.r?`<p><b>R</b> ${esc(g.r)}</p>`:""}<p><b>T</b> By ${dl(g.due)}</p><div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap">${auto?"":`<button class="btn s" data-a="gstep" data-id="${g.id}" data-v="-1">−1</button><button class="btn s" data-a="gset" data-id="${g.id}">Set progress</button>`}<button class="btn s" data-a="gedit" data-id="${g.id}">Edit</button><button class="btn s" style="color:var(--bad)" data-a="gdel" data-id="${g.id}">Delete</button></div></div>`:""}</div>`}

/* ================= money ================= */
const XC={Food:["cook","var(--acc)"],Groceries:["cart","var(--acc)"],Transport:["car","var(--acc)"],Rent:["today","var(--acc)"],Bills:["receipt","var(--acc)"],Work:["laptop","var(--acc)"],Shopping:["shirt","var(--acc)"],Health:["pulse","var(--acc)"],Fun:["film","var(--acc)"],Travel:["plane","var(--acc)"],Gifts:["gift","var(--acc)"],Other:["wallet","var(--acc)"]};
const IC={Salary:["briefcase","var(--acc)"],"Client payment":["coins","var(--acc)"],Freelance:["laptop","var(--acc)"],Investments:["chart","var(--acc)"],Gift:["gift","var(--acc)"],Other:["rupee","var(--acc)"]};
const inr=n=>(n<0?"−":"")+"₹"+Math.round(Math.abs(n)).toLocaleString("en-IN");
const catOf=t=>(t.k==="in"?IC:XC)[t.cat]||["wallet","#6b7280"];
const mKey=d=>d.slice(0,7),monthTx=m=>S.tx.filter(t=>mKey(t.d)===m);
function ensureRecurring(){const cur=iso(T).slice(0,7);let added=0;S.tx.filter(t=>t.rep==="monthly"&&!t.src).forEach(tp=>{const day=+tp.d.slice(8),d=P(tp.d.slice(0,7)+"-01");d.setMonth(d.getMonth()+1);
  while(iso(d).slice(0,7)<=cur){const m=iso(d).slice(0,7),last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate(),dd=m+"-"+String(Math.min(day,last)).padStart(2,"0");
   if(dd<=iso(T)&&!S.tx.some(x=>x.src===tp.id&&mKey(x.d)===m)&&!(tp.skip||[]).includes(m)){S.tx.push({...tp,id:nid(),d:dd,src:tp.id,rep:"none"});added++}d.setMonth(d.getMonth()+1)}});return added}
function settle(d,v,tx){d.paid=Math.round(((d.paid||0)+v)*100)/100;if(debtLeft(d)<=0.009){d.done=true;d.doneOn=iso(T)}if(tx)S.tx.push({id:nid(),k:d.dir==="owe"?"out":"in",amt:v,cat:"Other",note:d.dir==="owe"?"Paid back "+d.who:d.who+" paid me back",d:iso(T),rep:"none"});
 toast(d.done?"<b>All settled with "+esc(d.who)+"</b><p class='sm'>"+(tx?"Added to your "+(d.dir==="owe"?"expenses":"income")+".":"")+"</p>":"<b>"+inr(v)+" recorded</b><p class='sm'>"+inr(debtLeft(d))+" left.</p>")}
function moneyStats(m){const a=monthTx(m),inc=sum(a.filter(t=>t.k==="in").map(t=>t.amt)),out=sum(a.filter(t=>t.k==="out").map(t=>t.amt)),by={};a.filter(t=>t.k==="out").forEach(t=>by[t.cat]=(by[t.cat]||0)+t.amt);return{a,inc,out,net:inc-out,by}}
const debtLeft=d=>Math.max(0,d.amt-(d.paid||0));
const openDebts=dir=>S.debts.filter(d=>!d.done&&(!dir||d.dir===dir)).sort((a,b)=>(a.due||"9999").localeCompare(b.due||"9999")||b.id-a.id);
function debtRow(d){const left=debtLeft(d),od=d.due&&d.due<iso(T),dt=d.due?(od?`<span class="late">Overdue · was due ${dl(d.due)}</span>`:"Due "+dl(d.due)):"No due date";
 return`<div class="r" style="flex-wrap:wrap"><span class="hi sm2" style="--hc:${d.dir==="owe"?"var(--bad)":"var(--ok)"}">${svg("people")}</span><div class="g"><h3>${esc(d.who)}</h3><p class="sm mut">${d.note?esc(d.note)+" · ":""}${dt}</p>${d.paid?`<p class="sm mut">${inr(d.paid)} of ${inr(d.amt)} paid</p>`:""}</div><b class="${d.dir==="owe"?"":"ok"}">${inr(left)}</b>
 <div class="g3b"><button class="btn s" data-a="dpart" data-id="${d.id}">Part paid</button><button class="btn s p" data-a="dsettle" data-id="${d.id}">${d.dir==="owe"?"I paid it":"They paid"}</button><button class="xb" data-a="dmenu" data-id="${d.id}" aria-label="More">⋯</button></div>${S.openD===d.id?`<div style="display:flex;gap:8px;width:100%"><button class="btn s" data-a="dedit2" data-id="${d.id}">Edit</button><button class="btn s" style="color:var(--bad)" data-a="ddel2" data-id="${d.id}">Delete</button></div>`:""}</div>`}
function moneyChart(){const ms=[];const d=new Date(T.getFullYear(),T.getMonth(),1);for(let i=5;i>=0;i--){const x=new Date(d.getFullYear(),d.getMonth()-i,1);ms.push(iso(x).slice(0,7))}
 const st=ms.map(m=>moneyStats(m)),mx=Math.max(1,...st.map(s=>Math.max(s.inc,s.out))),W=360,H=150,bw=16,gap=(W-20)/6;
 return`<svg viewBox="0 0 ${W} ${H+22}" width="100%" role="img" aria-label="Income and spending, last 6 months">${st.map((s,i)=>{const x=14+i*gap+gap/2-bw-2,hi=s.inc/mx*H,ho=s.out/mx*H,sel=ms[i]===S.mv;return`<rect x="${x}" y="${H-hi}" width="${bw}" height="${Math.max(hi,1)}" rx="3" fill="var(--ok)" opacity="${sel?1:.55}"/><rect x="${x+bw+4}" y="${H-ho}" width="${bw}" height="${Math.max(ho,1)}" rx="3" fill="var(--bad)" opacity="${sel?1:.55}"/><text x="${x+bw+2}" y="${H+16}" text-anchor="middle" font-size="11" fill="${sel?"var(--ink)":"var(--mut)"}" font-weight="${sel?600:400}">${MON[+ms[i].slice(5)-1]}</text>`}).join("")}</svg>`}
function txRow(t){const[ic,col]=catOf(t),op=S.openX===t.id;return`<div class="dr"><button class="drow" data-a="xopen" data-id="${t.id}"><span class="hi sm2" style="--hc:${col}">${svg(ic)}</span><span class="g"><span class="nm">${esc(t.note||t.cat)}</span><span class="sm mut">${esc(t.cat)}${t.rep==="monthly"||t.src?" · Monthly":""}</span></span><b class="${t.k==="in"?"ok":""}">${t.k==="in"?"+":"−"}${inr(t.amt).replace("−","")}</b></button>
 ${op?`<div class="dx" style="padding-left:54px"><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn s" data-a="xedit" data-id="${t.id}">Edit</button>${t.rep==="monthly"||t.src?`<button class="btn s" data-a="xstop" data-id="${t.id}">Stop repeating</button>`:""}<button class="btn s" style="color:var(--bad)" data-a="xdel" data-id="${t.id}">Delete</button></div></div>`:""}</div>`}

/* ================= custom reminders ================= */
const RREP={once:"Once",daily:"Every day",weekdays:"Weekdays",weekly:"Some days",monthly:"Monthly"};
function remHits(r,D){const ds=iso(D);if(r.rep==="once")return r.d===ds;if(r.d&&ds<r.d)return false;const g=D.getDay();if(r.rep==="daily")return true;if(r.rep==="weekdays")return g>0&&g<6;if(r.rep==="weekly")return(r.days||[]).includes(g);if(r.rep==="monthly"){const sd=P(r.d||ds).getDate();return D.getDate()===Math.min(sd,new Date(D.getFullYear(),D.getMonth()+1,0).getDate())}return false}
function remLabel(r){if(r.rep==="once")return dl(r.d)+" at "+r.time;if(r.rep==="weekly")return(r.days||[]).slice().sort((a,b)=>((a+6)%7)-((b+6)%7)).map(d=>WD[d]).join(", ")+" at "+r.time;if(r.rep==="monthly")return"Every month on the "+P(r.d).getDate()+ord(P(r.d).getDate())+" at "+r.time;return RREP[r.rep]+" at "+r.time}
const ord=n=>n%100>=11&&n%100<=13?"th":["th","st","nd","rd"][n%10]||"th";
function remRow(r){return`<div class="r"><span class="hi sm2" style="--hc:${r.on===false?"var(--mut)":"var(--acc)"}">${svg("bell")}</span><div class="g" data-a="remedit" data-id="${r.id}" style="cursor:pointer"><h3 style="${r.on===false?"color:var(--mut)":""}">${esc(r.t)}</h3><p class="sm mut">${remLabel(r)}${r.note?" · "+esc(r.note):""}</p></div><label class="sw2" aria-label="${r.on===false?"Turn on":"Turn off"}"><input type="checkbox" data-a="remtog" data-id="${r.id}" ${r.on===false?"":"checked"}><span></span></label><button class="iconbtn rdel" data-a="remdel" data-id="${r.id}" aria-label="Delete ${esc(r.t)}">${svg("trash")}</button></div>`}
/* ================= wheel pickers (iOS style) ================= */
const fmtT=t=>{if(!t)return"";const[h,m]=t.split(":").map(Number);return(h%12||12)+":"+String(m).padStart(2,"0")+" "+(h<12?"AM":"PM")};
const fmtD=v=>v?(diff(v)===0?"Today":diff(v)===1?"Tomorrow":diff(v)===-1?"Yesterday":WD[P(v).getDay()]+", "+fmt(P(v))+(P(v).getFullYear()!==T.getFullYear()?" "+P(v).getFullYear():"")):"";
const fmtDM=v=>v?(+v.slice(3))+" "+MONL[+v.slice(0,2)-1]:"";
function pf(bind,type,val,o){o=o||{};const lab=type==="time"?fmtT(val):type==="dm"?fmtDM(val):fmtD(val);return`<button type="button" class="pf ${val?"":"empty"}" data-a="pick" data-bind="${bind}" data-type="${type}" data-val="${val||""}" ${o.clear?'data-clear="1"':""} ${o.yr?`data-yr="${o.yr}"`:""}>${svg(type==="time"?"clock":"cal")}<span>${lab||o.none||"Pick"}</span><i>›</i></button>`}
const rng=(a,b)=>Array.from({length:b-a+1},(_,i)=>a+i);
let PK=null;
function openPick(el){const type=el.dataset.type,val=el.dataset.val;PK={type,bind:el.dataset.bind,clear:!!el.dataset.clear,yr:el.dataset.yr};
 if(type==="time"){const n=new Date(),[h,m]=(val||String((n.getHours()+1)%24).padStart(2,"0")+":00").split(":").map(Number);PK.v={h:h%12||12,m,ap:h<12?0:1}}
 else if(type==="dm"){PK.v={d:val?+val.slice(3):T.getDate(),mo:val?+val.slice(0,2)-1:T.getMonth()}}
 else{const d=val?P(val):(PK.yr==="past"?new Date(T.getFullYear()-25,T.getMonth(),T.getDate()):T);PK.v={d:d.getDate(),mo:d.getMonth(),y:d.getFullYear()}}
 drawPick()}
function pkCols(){if(PK.type==="time")return[["h",rng(1,12).map(x=>[x,String(x)])],["m",rng(0,59).map(x=>[x,String(x).padStart(2,"0")])],["ap",[[0,"AM"],[1,"PM"]]]];
 const c=[["d",rng(1,31).map(x=>[x,String(x)])],["mo",MONL.map((x,i)=>[i,x])]];if(PK.type==="date"){const y0=PK.yr==="past"?T.getFullYear()-90:T.getFullYear()-1;c.push(["y",rng(y0,T.getFullYear()+(PK.yr==="past"?0:4)).map(x=>[x,String(x)])])}return c}
function pkQuick(){if(PK.type==="time")return[["now","Now"],["+60","In 1 hour"],["07:00","7 AM"],["09:00","9 AM"],["13:00","1 PM"],["18:00","6 PM"],["21:00","9 PM"]];if(PK.type==="date"&&PK.yr!=="past")return[["0","Today"],["1","Tomorrow"],["mon","Next Monday"],["7","In a week"]];return[]}
function drawPick(){const el=$("#picker");if(!PK){el.classList.remove("show");el.innerHTML="";return}const q=pkQuick(),cols=pkCols();
 el.innerHTML=`<div class="pkbg" data-a="pkcancel"></div><div class="pkp" role="dialog" aria-label="Pick ${PK.type==="time"?"a time":"a date"}"><div class="pkh"><button data-a="pkcancel">Cancel</button><b>${PK.type==="time"?"Time":PK.type==="dm"?"Birthday":"Date"}</b><button class="pkdone" data-a="pkdone">Done</button></div>
 ${q.length?`<div class="chips pkq">${q.map(([v,t])=>`<button class="chip" data-a="pkq" data-v="${v}">${t}</button>`).join("")}</div>`:""}
 <div class="wheel ${PK.type}"><div class="band"></div>${cols.map(([k,it])=>`<div class="col" data-k="${k}">${it.map(([v,l])=>`<div class="it" data-v="${v}">${l}</div>`).join("")}</div>`).join("")}</div>
 ${PK.clear?`<button class="link" data-a="pkclear">${PK.type==="time"?"No time":"Clear"}</button>`:""}</div>`;
 el.classList.add("show");el.querySelectorAll(".col").forEach(c=>{const k=c.dataset.k,items=[...c.children],i=Math.max(0,items.findIndex(x=>+x.dataset.v===PK.v[k]));c.scrollTop=i*44;mark(c);c._j=Math.round(c.scrollTop/44);c.addEventListener("scroll",()=>{const j=Math.round(c.scrollTop/44);if(j!==c._j){c._j=j;buzz("sel")}});let t;c.addEventListener("scroll",()=>{clearTimeout(t);t=setTimeout(()=>{const j=Math.min(items.length-1,Math.max(0,Math.round(c.scrollTop/44)));PK.v[k]=+items[j].dataset.v;mark(c)},70)});c.addEventListener("click",e=>{const it=e.target.closest(".it");if(it){c.scrollTo({top:items.indexOf(it)*44,behavior:"smooth"})}})})}
function mark(c){const j=Math.round(c.scrollTop/44);[...c.children].forEach((x,i)=>x.classList.toggle("sel",i===j))}
function pkValue(){const v=PK.v;if(PK.type==="time"){const h=v.ap?(v.h%12)+12:v.h%12;return String(h).padStart(2,"0")+":"+String(v.m).padStart(2,"0")}
 const dim=new Date(PK.type==="dm"?2024:v.y,v.mo+1,0).getDate(),d=Math.min(v.d,dim);if(PK.type==="dm")return String(v.mo+1).padStart(2,"0")+"-"+String(d).padStart(2,"0");return iso(new Date(v.y,v.mo,d))}
function applyPick(bind,v){if(bind.startsWith("form."))S.form[bind.slice(5)]=v;else if(bind.startsWith("task:")){const[,id,f]=bind.split(":"),x=S.todos.find(y=>y.id==id);if(x)x[f]=v||(f==="d"?iso(T):"")}else S[bind]=v}
function pkQuickSet(q){const v=PK.v;if(PK.type==="time"){let d=new Date();if(q==="+60")d=new Date(Date.now()+36e5);else if(q!=="now"){const[h,m]=q.split(":").map(Number);d.setHours(h,m)}v.h=d.getHours()%12||12;v.m=d.getMinutes();v.ap=d.getHours()<12?0:1}
 else{let d=new Date(T);if(q==="mon")d=add(monday(T),7);else d=add(T,+q);v.d=d.getDate();v.mo=d.getMonth();v.y=d.getFullYear()}drawPick()}

/* ================= sleep timer ================= */
function toBed(){S.sleepAt=Date.now();try{const w=plug("BirdieWidgets");if(w)w.sleepStart({at:S.sleepAt}).catch(()=>{})}catch(e){}toast(isAndroid()?"<b>Sleep well</b><p class='sm'>I’ve put a timer in your notifications. Tap “I’m awake” there in the morning.</p>":"<b>Sleep well</b><p class='sm'>Open Birdie and tap “I’m awake” when you get up.</p>")}
function logSleep(st,end){const min=Math.round((end-st)/6e4);try{const w=plug("BirdieWidgets");if(w)w.sleepStop().catch(()=>{})}catch(e){}S.sleepAt=null;
 if(min<10){toast("<b>Under 10 minutes</b><p class='sm'>Not logged.</p>");return}
 if(min<180&&st.getHours()>=9&&st.getHours()<20){S.naps.push({d:iso(end),min,at:hm(st)});toast("<b>Nap logged</b><p class='sm'>"+fmtDur(min)+", from "+fmtT(hm(st))+".</p>");return}
 const d=iso(end);S.sleep=S.sleep.filter(x=>x.d!==d);S.sleep.push({d,b:hm(st),w:hm(end)});S.lastBed=hm(st);S.lastWake=hm(end);S.birdMsg={m:"happy",t:(end.getHours()<12?"Good morning! ":"Welcome back! ")+"You slept "+fmtDur(min)+".",d:iso(T)};toast("<b>"+(end.getHours()<12?"Good morning":"Welcome back")+"</b><p class='sm'>You slept "+fmtDur(min)+", "+fmtT(hm(st))+" to "+fmtT(hm(end))+".</p>")}
function awake(endMs){if(!S.sleepAt)return;const st=new Date(S.sleepAt),end=new Date(endMs||Date.now()),min=Math.round((end-st)/6e4);
 if(min>10*60&&!endMs){openSheet("wakefix",{b:hm(st),w:hm(end),bd:iso(st),d:iso(end)});return true}
 logSleep(st,end)}
const sleepBtn=(cls)=>S.sleepAt?`<button class="btn p ${cls||""}" data-a="awake">${svg("sun","bi wh")} I’m awake</button>`:`<button class="btn ${cls||""}" data-a="tobed">${svg("moon","bi")} Going to bed</button>`;

