const sinceTxt=d=>{const n=-diff(d||iso(T));return n<1?"today":n<14?n+" days ago":n<60?Math.round(n/7)+" weeks ago":Math.round(n/30)+" months ago"};

/* ================= year in pixels + mood patterns ================= */
function moodPatterns(){const md={};S.moods.forEach(m=>md[m.d]=m.v);const ks=Object.keys(md);if(ks.length<6)return[];const out=[];
 S.habits.filter(h=>!isScr(h)).forEach(h=>{const a=[],b=[];ks.forEach(k=>{if(h.created&&k<h.created)return;if(!hSched(h)(P(k)))return;(hDone(h,k)?a:b).push(md[k])});if(a.length>=3&&b.length>=3){const d=mean(a)-mean(b);if(d>=.3)out.push({d,t:"Your mood is "+d.toFixed(1)+" higher on days you do “"+h.n+"”."})}});
 const sl={};S.sleep.forEach(e=>sl[e.d]=sleepMin(e));const g=[],l=[];ks.forEach(k=>{if(sl[k]!=null)(sl[k]>=7*60?g:l).push(md[k])});if(g.length>=3&&l.length>=3){const d=mean(g)-mean(l);if(d>=.3)out.push({d,t:"After 7+ hours of sleep your mood is "+d.toFixed(1)+" higher."})}
 const wg=[],wl=[];ks.forEach(k=>{if(S.water.log[k]!=null)(S.water.log[k]>=S.water.goal?wg:wl).push(md[k])});if(wg.length>=3&&wl.length>=3){const d=mean(wg)-mean(wl);if(d>=.3)out.push({d,t:"On days you hit your water goal, your mood is "+d.toFixed(1)+" higher."})}
 return out.sort((a,b)=>b.d-a.d).slice(0,3)}
function pixelsView(){const y=S.py||T.getFullYear(),md={};S.moods.forEach(m=>md[m.d]=m.v);const pats=moodPatterns(),n=Object.keys(md).filter(k=>k.startsWith(y+"")).length,av=n?mean(Object.keys(md).filter(k=>k.startsWith(y+"")).map(k=>md[k])):0;
 let g=`<span></span>${MON.map(m=>`<b>${m[0]}</b>`).join("")}`;for(let d=1;d<=31;d++){g+=`<small>${d%5===0||d===1?d:""}</small>`;for(let m=0;m<12;m++){const dt=new Date(y,m,d),k=iso(dt),ok=dt.getMonth()===m;const v=ok?md[k]:null;g+=ok?`<i class="${dt>T?"fut":""}" style="${v?`--v:${v}`:""}" ${v?`data-v="${v}" data-a="pixday" data-d="${k}"`:""} title="${k}${v?": "+v+"/5":""}"></i>`:"<span></span>"}}
 return`<div class="top"><div class="lt">${backBtn("sub")}<h1>Year in pixels</h1></div></div>
 <div class="r sb" style="border:0;padding:0 0 10px"><button class="iconbtn" data-a="py" data-v="-1" aria-label="Previous year">${ico("left")}</button><b>${y}</b><button class="iconbtn" data-a="py" data-v="1" aria-label="Next year" ${y>=T.getFullYear()?"disabled":""}>${ico("right")}</button></div>
 <div class="box"><div class="pix">${g}</div><div class="pleg"><span class="sm mut">Low</span>${[1,2,3,4,5].map(v=>`<i style="--v:${v}" data-v="${v}"></i>`).join("")}<span class="sm mut">Great</span></div><p class="sm mut" style="margin-top:8px">${n?plural(n,"day")+" logged · average "+av.toFixed(1)+" out of 5":"Log your mood on the Habits tab and your year fills in, one square a day."}</p></div>
 <h2>What lifts your mood</h2><div class="box">${pats.length?pats.map(p=>`<div class="pat">${birdSvg("happy",34)}<p>${esc(p.t)}</p></div>`).join(""):`<div class="pat">${birdSvg("normal",34)}<p class="mut">Log your mood for a couple of weeks and I’ll spot what makes your good days good.</p></div>`}</div>`}

