function jar(pc){const h=Math.max(0,Math.min(100,pc));return`<svg viewBox="0 0 48 60" class="jar" aria-hidden="true"><defs><clipPath id="jc${Math.round(pc*7)}"><path d="M10 14h28v36a6 6 0 0 1-6 6H16a6 6 0 0 1-6-6z"/></clipPath></defs><rect x="14" y="4" width="20" height="8" rx="3" class="lid"/><path d="M10 14h28v36a6 6 0 0 1-6 6H16a6 6 0 0 1-6-6z" class="glass"/><g clip-path="url(#jc${Math.round(pc*7)})"><rect x="8" y="${56-42*h/100}" width="32" height="44" class="fill"/></g></svg>`}
