function confetti(cv,cols){if(!cv)return;const ctx=cv.getContext("2d"),W=cv.width=innerWidth*devicePixelRatio,H=cv.height=innerHeight*devicePixelRatio;const ps=Array.from({length:160},()=>({x:W/2,y:H*.42,vx:(Math.random()-.5)*W*.03,vy:-Math.random()*H*.03-H*.008,s:(6+Math.random()*8)*devicePixelRatio,r:Math.random()*6,vr:(Math.random()-.5)*.3,c:cols[Math.floor(Math.random()*cols.length)],sh:Math.random()<.5}));let f=0;
 (function loop(){if(!cv.isConnected)return;ctx.clearRect(0,0,W,H);ps.forEach(p=>{p.vy+=H*.0009;p.vx*=.99;p.x+=p.vx;p.y+=p.vy;p.r+=p.vr;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.r);ctx.fillStyle=p.c;if(p.sh)ctx.fillRect(-p.s/2,-p.s/4,p.s,p.s/2);else{ctx.beginPath();ctx.arc(0,0,p.s/3,0,7);ctx.fill()}ctx.restore()});if(++f<240)requestAnimationFrame(loop)})()}

