  if(s===0)ch.forEach(m=>tone(ctx,out,mtof(m+12),t,MUS.sd*15,"triangle",.045,1400));
  if([0,6,10].includes(s))tone(ctx,out,mtof(ch[0]-12),t,MUS.sd*(s===0?5:3),"triangle",.22,600);
  if(s===0||s===8||(s===11&&bar%2))kick(ctx,out,t);if(s===4||s===12)hit(ctx,out,t,"bandpass",1800,.14,.16);if(s%2===0)hit(ctx,out,t+(s%4?MUS.sd*.1:0),"highpass",7500,s%4?.03:.05,.05);
