function quickAdd(){const v=S.qa.trim();if(!v){toast("<b>Type a task first</b>");return}S.todos.push({id:nid(),t:v,d:iso(T),rem:"",rep:"none",star:false,subs:[],done:false,ord:maxOrd()+1});S.qa="";render();const i=$("#qa");if(i)i.focus()}
function addStep(id){const i=$("#subin"),v=i&&i.value.trim();if(!v)return;const x=S.todos.find(y=>y.id===id);x.subs=x.subs||[];x.subs.push({t:v,done:false});render();const j=$("#subin");if(j)j.focus()}
document.addEventListener("keydown",e=>{if(e.key!=="Enter")return;if(e.target.id==="qa"){e.preventDefault();quickAdd()}else if(e.target.id==="subin"){e.preventDefault();addStep(+e.target.dataset.sub)}});

/* swipe on to-do rows: right = done, left = tomorrow */
let sw=null;
let lp=null,drag=null;
document.addEventListener("pointerdown",e=>{const r=e.target.closest(".tdo[data-sw]");if(!r||e.target.closest("input,button"))return;sw={r,x:e.clientX,y:e.clientY,dx:0,on:false,pid:e.pointerId};
 if(r.closest("#tdl")&&!r.classList.contains("dn"))lp={x:e.clientX,y:e.clientY,t:setTimeout(()=>startDrag(r),380)}});
function startDrag(r){lp=null;if(sw&&sw.on)return;sw=null;const w=r.closest(".swr");drag={w,list:w.parentNode};w.classList.add("lift");document.body.classList.add("dragging");buzz("tap");}
function moveDrag(y){const sib=[...drag.list.querySelectorAll(":scope>.swr")].filter(z=>z!==drag.w&&z.querySelector(".tdo[data-sw]:not(.dn)"));let tgt=null,mode=null;
 for(const z of sib){const b=z.getBoundingClientRect(),mid=b.top+b.height/2,pre=z.compareDocumentPosition(drag.w)&Node.DOCUMENT_POSITION_FOLLOWING;if(pre&&y<mid&&!tgt){tgt=z;mode="b"}if(!pre&&y>mid){tgt=z;mode="a"}}
 if(tgt){if(mode==="b")drag.list.insertBefore(drag.w,tgt);else tgt.after(drag.w)}if(y<90)scrollBy(0,-10);else if(y>innerHeight-150)scrollBy(0,10)}
function endDrag(){S.tipSeen=true;const ids=[...drag.list.querySelectorAll(".tdo[data-sw]:not(.dn)")].map(z=>+z.dataset.sw);ids.forEach((id,i)=>{const x=S.todos.find(y=>y.id===id);if(x)x.ord=i+1});drag.w.classList.remove("lift");document.body.classList.remove("dragging");drag=null;swiped=Date.now();render()}
document.addEventListener("touchmove",e=>{if(drag)e.preventDefault()},{passive:false});
document.addEventListener("contextmenu",e=>{if(e.target.closest(".tdo"))e.preventDefault()});
document.addEventListener("pointermove",e=>{if(drag){e.preventDefault();moveDrag(e.clientY);return}if(lp&&(Math.abs(e.clientX-lp.x)>8||Math.abs(e.clientY-lp.y)>8)){clearTimeout(lp.t);lp=null}if(!sw)return;const dx=e.clientX-sw.x,dy=e.clientY-sw.y;if(!sw.on){if(Math.abs(dx)>12&&Math.abs(dx)>Math.abs(dy)*1.5){sw.on=true;sw.r.style.transition="none";try{sw.r.setPointerCapture(sw.pid)}catch(_){}}else if(Math.abs(dy)>12){sw=null;return}else return}
 sw.dx=dx;sw.r.style.transform=`translateX(${dx}px)`;const p=sw.r.parentNode,l=p.querySelector(".swl"),rr=p.querySelector(".swrr");if(l)l.style.opacity=dx>0?Math.min(1,dx/90):0;if(rr)rr.style.opacity=dx<0?Math.min(1,-dx/90):0});
function endSwipe(){if(!sw)return;const s=sw;sw=null;if(!s.on)return;S.tipSeen=true;swiped=Date.now();const id=+s.r.dataset.sw,x=S.todos.find(y=>y.id===id);s.r.style.transition="transform .2s";
 if(s.dx<-90&&x){s.r.style.transform="translateX(-110%)";setTimeout(()=>{setDone(x,true);toast("<b>Done</b><p class='sm'>"+esc(x.t)+"</p>");render()},180)}
 else if(s.dx>90&&x){buzz("tap");s.r.style.transform="translateX(110%)";setTimeout(()=>{x.d=iso(add(T,1));if(x.rem&&false)x.rem="";toast("<b>Moved to tomorrow</b><p class='sm'>"+esc(x.t)+"</p>");render()},180)}
 else{s.r.style.transform="";const p=s.r.parentNode;p.querySelectorAll(".swl,.swrr").forEach(z=>z.style.opacity=0)}}
const pEnd=()=>{if(lp){clearTimeout(lp.t);lp=null}if(drag){sw=null;endDrag();return}endSwipe()};document.addEventListener("pointerup",pEnd);document.addEventListener("pointercancel",pEnd);

/* keep the screen fresh: new day, reminders becoming due */
setInterval(()=>{const before=iso(T);refreshDay();const ae=document.activeElement,typing=ae&&/INPUT|TEXTAREA|SELECT/.test(ae.tagName);if(!typing&&!S.sheet&&!sw&&!drag&&(before!==iso(T)||S.tab==="today"||S.tab==="todo"))render();if(!typing&&!sw&&!drag)maybeNudge(.08)},30000);
setTimeout(()=>maybeNudge(.6),4000);
if(S.birdMsg&&S.birdMsg.seen)S.birdMsg=null;
const hasData=!!(S.todos.length||S.habits.length||S.moods.length||S.people.length||S.reminders.length||S.tx.length||S.w.length||S.sleep.length);
if(!S.onboarded&&hasData)S.onboarded=true;
if(S.owned==null){const v4=["party","shades","scarf","beanie","bow","bowtie","specs","phones","flower","chain","hearts","crown","wizard"],lv=xpInfo().lvl;S.owned=OUTFITS.filter(o=>v4.includes(o.id)&&o.lvl<=lv).map(o=>o.id);Object.values(S.outfit||{}).forEach(id=>{if(id&&!S.owned.includes(id))S.owned.push(id)})}
if(S.verSeen!==APP_VER){if(S.onboarded&&hasData)S.birdMsg={m:"wow",t:"New update! I can show your screen time now and turn app limits into habits that tick themselves. Have a look in Habits → Screen time 📱"};S.verSeen=APP_VER}
if(!native()&&"serviceWorker"in navigator&&location.protocol==="https:")navigator.serviceWorker.register("sw.js").catch(()=>{});
render();initNative();if(S.sleepAt&&Date.now()-S.sleepAt>12*36e5)setTimeout(()=>{if(!S.sheet&&S.sleepAt){const st=new Date(S.sleepAt),e=new Date();openSheet("wakefix",{b:hm(st),w:hm(e),d:iso(e)})}},900);
